formula_sources.getTierTooltipStats:
function getTierTooltipStats(slot, tier) {
                    tier = Math.max(0, parseInt(tier || 0, 10) || 0);
                    if (tier <= 0) return [];
                    switch (slot) {
                        case 'weapon':
                        case 'ammo':
                            return [`Tier Crit Chance: +${(tier * 0.5).toFixed(1)}%`, `Tier Crit Dmg: +${tier}%`];
                        case 'shield':
                            return [`Tier Reflect: +${tier}%`];
                        case 'helmet':
                            return [`Tier Mana Leech: +${(tier * 0.3).toFixed(1)}%`];
                        case 'armor':
                            return [`Tier Life Leech: +${(tier * 0.3).toFixed(1)}%`];
                        case 'legs':
                            return [`Tier Dodge: +${(tier * 0.3).toFixed(1)}%`];
                        case 'boots':
                            return [`Tier Speed: +${tier * 5}`, 'Speed a partir de 40 acelera a próxima leva.'];
                        case 'ring':
                            return [`Tier Dano: +${tier}%`];
                        case 'amulet':
                            return [`Tier XP: +${tier}%`];
                        default:
                            return [];
                    }
                }

formula_sources.describeTierBonus:
function describeTierBonus(slot, tier) {
                    const cur = tier;
                    const next = Math.min(10, tier + 1);
                    const line = (label, curVal, nextVal, suffix = '%') =>
                        `${label}: +${curVal}${suffix} <span style="color:#6fbf73;">→ +${nextVal}${suffix}</span>`;

                    switch (slot) {
                        case 'weapon':
                        case 'ammo':
                            return line('Crit Chance', (cur * 0.5).toFixed(1), (next * 0.5).toFixed(1))
                                + '<br>' + line('Crit Dmg', cur * 1, next * 1);
                        case 'shield':
                            return line('Reflect', cur * 1, next * 1);
                        case 'helmet':
                            return line('Mana Leech', (cur * 0.3).toFixed(1), (next * 0.3).toFixed(1));
                        case 'armor':
                            return line('Life Leech', (cur * 0.3).toFixed(1), (next * 0.3).toFixed(1));
                        case 'legs':
                            return line('Dodge', (cur * 0.3).toFixed(1), (next * 0.3).toFixed(1));
                        case 'boots':
                            return line('Speed', cur * 5, next * 5, '');
                        case 'ring':
                            return line('Dano', cur * 1, next * 1);
                        case 'amulet':
                            return line('XP', cur, next);
                        default:
                            return '';
                    }
                }

formula_sources.renderForgeList:
function renderForgeList(data) {
                    const corpo = document.getElementById('forge-body');
                    if (!corpo) return;
                    const receitas = data.receitas || [];
                    if (!receitas.length) {
                        corpo.innerHTML = '<div style="color:#9db3d6; font-size:12.5px; text-align:center; padding:28px; line-height:1.6;">Nenhuma receita disponível para a sua vocação.</div>';
                        return;
                    }

                    const fmt = n => Math.floor(n).toLocaleString('pt-BR');
                    corpo.innerHTML = receitas.map(r => {
                        const passos = r.steps.map(s => {
                            const cor = s.ok ? '#81c784' : '#ff8a65';
                            const marca = s.ok ? '✔' : '✘';
                            // "aceita" lista as variantes válidas — é o que o jogador precisa
                            // procurar quando o passo está vermelho.
                            const aceita = s.aceita.join(' ou ');
                            const onde = s.ok ? ` <span style="color:#7d8aa0;">(${s.origem === 'deposito' ? 'banco' : 'mochila'}, T${s.tier})</span>` : '';
                            return `<div style="display:flex; gap:7px; align-items:flex-start; padding:3px 0; font-size:11.5px;">
                                <span style="color:${cor}; flex-shrink:0; font-weight:bold;">${marca}</span>
                                <span style="color:#dbe7fa; flex-shrink:0; min-width:132px;">${escapeTooltipLine(s.label)}</span>
                                <span style="color:${cor};">${escapeTooltipLine(aceita)}${onde}</span>
                            </div>`;
                        }).join('');

                        const corOrb = r.orbs_ok ? '#81c784' : '#ff8a65';
                        const corGold = r.gold_ok ? '#81c784' : '#ff8a65';
                        const btn = r.pode
                            ? `<button onclick="forjarArma('${r.chave}','${escapeTooltipLine(r.result_name)}')" class="gold-pulse-btn" style="width:100%; margin-top:10px; padding:10px; background:linear-gradient(to bottom,#d4a85a,#8c5a1d); border:1px solid #43290c; color:#fff; border-radius:5px; font-family:'MedievalSharp',cursive; font-weight:bold; font-size:13px; cursor:pointer;">🔨 FORJAR ${escapeTooltipLine(r.result_name).toUpperCase()}</button>`
                            : `<div style="width:100%; margin-top:10px; padding:9px; text-align:center; background:rgba(0,0,0,0.25); border:1px dashed rgba(255,138,101,0.4); border-radius:5px; color:#9db3d6; font-size:11.5px;">Faltam ingredientes</div>`;

                        return `<div style="border:2px solid ${r.pode ? '#d4a85a' : '#3a4a66'}; border-radius:8px; padding:12px 14px; margin-bottom:14px; background:rgba(0,0,0,0.22);">
                            <div style="display:flex; align-items:center; gap:10px; margin-bottom:9px;">
                                <img src="${itemImagesUrl}${r.result_id}.gif" style="width:38px; height:38px; image-rendering:pixelated; flex-shrink:0;" alt="">
                                <div style="min-width:0;">
                                    <div style="font-family:'MedievalSharp',cursive; font-size:15px; color:#f5e3c0; font-weight:bold;">${escapeTooltipLine(r.result_name)}</div>
                                    <div style="font-size:10.5px; color:#9db3d6;">${escapeTooltipLine(r.tipo)} · vai para o Banco</div>
                                </div>
                            </div>
                            ${passos}
                            <div style="display:flex; gap:16px; margin-top:8px; padding-top:8px; border-top:1px solid rgba(111,159,216,0.2); font-size:11.5px;">
                                <span style="color:${corOrb};">${r.orbs_ok ? '✔' : '✘'} Forge Orb ${r.orbs_tem}/${r.orbs_precisa}</span>
                                <span style="color:${corGold};">${r.gold_ok ? '✔' : '✘'} ${fmt(r.gold_precisa)} Gold</span>
                            </div>
                            ${btn}
                        </div>`;
                    }).join('');
                }
